const m = $input.first().json.body || $input.first().json;
const system = "<private instructions: kept out of this repository>";
const user = "Caller: " + (m.name || m.caller || "?") + ", " + (m.company || "") + ", " + (m.country || "") + "\nCall length (s): " + (m.duration || "?") + "\nTranscript:\n" + (m.transcript || m.analysis?.transcript_summary || JSON.stringify(m).slice(0, 4000));
const schema = {"type":"object","additionalProperties":false,"required":["summary","outcome","brand","wants","follow_up","follow_up_in_days","hot_score"],"properties":{"summary":{"type":"string"},"outcome":{"type":"string","enum":["interested","call_back","not_interested","no_answer","wrong_number"]},"brand":{"type":"string"},"wants":{"type":"string"},"follow_up":{"type":"string"},"follow_up_in_days":{"type":"integer"},"hot_score":{"type":"integer"}}};
return [{ json: { input: m, 
  grok: { model: "grok-4.7", temperature: 0, messages: [{ role: "system", content: system }, { role: "user", content: user }],
    response_format: { type: "json_schema", json_schema: { name: "answer", strict: true, schema } } },
  claude: { model: "claude-opus-5-5", max_tokens: 3000, output_config: { effort: "low", format: { type: "json_schema", schema } },
    system, messages: [{ role: "user", content: user }] } } }];

const j = $input.first().json;
let text, ai;
if (j.choices) { text = j.choices[0].message.content; ai = "Grok 4.7 (xAI)"; }
else { if (j.stop_reason === "refusal") throw new Error("Claude declined"); text = (j.content || []).filter(b => b.type === "text").map(b => b.text).join(""); ai = "Claude Opus 5.5 (backup)"; }
let a; try { a = JSON.parse(text); } catch (e) { throw new Error("AI answer was not valid JSON"); }
const input = $('Prepare the call notes').first().json.input;
const hot = Math.max(0, Math.min(10, a.hot_score | 0));
const values = {
  "__drop385": input.company || "", "text_mm9cnab6": input.country || "", "color_mm9c3svj": a.brand, "text_mm9c5emj": String(a.wants).slice(0, 250),
  "__drop386": "call_" + a.outcome + " (" + ai + ")", "numeric_mm9cw74a": String(hot), "color_mm9c54h3": "telecaller",
  "__drop388": { text: a.summary }, "text_mm9cv10y": { text: a.follow_up } };
return [{ json: { ai, call: a, monday: { query: "mutation ($b: ID!, $n: String!, $v: JSON!) { create_item(board_id: $b, item_name: $n, column_values: $v, create_labels_if_missing: true) { id } }",
    variables: { b: "<monday-board-id>", n: (input.name || input.caller || "Call") + " (AI telecaller)", v: JSON.stringify(Object.fromEntries(Object.entries(values).filter(([k]) => !k.startsWith("__drop")).map(([k, v]) => [k, ["color_mm9cpd1j","color_mm9c1s94","color_mm9c54h3","color_mm9c38n","color_mm9c3svj","color_mm9ck3pv"].includes(k) && typeof v !== "object" ? { label: String(v).replace(/^./, (x) => x.toUpperCase()) } : v]))) } } } }];

const row = $('Add call row on Monday').first().json;
const call = $('Read the AI answer and build the Monday row').first().json.call;
const parent = row.data?.create_item?.id;
if (!parent) return [{ json: { skipped: true, why: "Monday row was not created, so no follow-up task" } }];
return [{ json: { monday: { query: "mutation ($p: ID!, $n: String!) { create_subitem(parent_item_id: $p, item_name: $n) { id } }",
  variables: { p: String(parent), n: "FOLLOW UP in " + call.follow_up_in_days + " day(s): " + call.follow_up } } } }];
